STORY_DARK_FOREST_61_70 = (
    V2StoryQuestContentRecord('dark_forest_061_sortie_orders', 61, 'Наказ про вилазки', 'TALK', 'dark_forest', 7, 'dark_forest_060_threat_from_the_depths', 'mercenary_head', 'mercenary_head', 1, 'Після доповіді Старості Голова Найманців розпочинає операцію проти внутрішніх гоблінських стоянок.', 'Отримати від Голови Найманців наказ про подальші вилазки.', 'Староста затвердив операцію. Відтепер ми не просто захищаємо старий шлях, а намагаємося зрозуміти, як працює мережа гоблінських дозорів.\n\nРозвідники нанесли на карту кілька стоянок. Окремо вони не схожі на великі табори, але між ними постійно рухаються патрулі. Один загін змінює інший, а на високих деревах чергують спостерігачі.\n\nЦі стоянки діють узгоджено. Патрулі підтримують зв’язок і контролюють внутрішні стежки значно краще, ніж ми припускали після першої розвідки.', 'Голова Найманців завершує доповідь про розташування внутрішніх стоянок і узгоджений рух гоблінських патрулів.', 75, 2.36, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_062_changing_of_the_guard', 62, 'Зміна варти', 'KILL_REGION', 'dark_forest', 7, 'dark_forest_061_sortie_orders', 'mercenary_head', 'mercenary_head', 8, 'Гравець атакує гоблінські патрулі під час зміни варти, щоб порушити рух між внутрішніми стоянками.', 'Перемогти 8 будь-яких істот у локації Темний Бір.', 'Патрулі змінюються біля старого поваленого дуба. Саме там зустрічаються загони з північної та західної стежок.\n\nПід час зміни варти обидві групи ненадовго збираються в одному місці. Це дозволить завдати удару до того, як сусідні стоянки зрозуміють, що сталося.\n\nПереможи вісім ворогів і повернися з доповіддю. Не відходь далеко від позначеної ділянки.', 'Зміну варти зірвано. Гоблінські патрулі втратили контроль над ділянкою біля поваленого дуба.', 75, 2.36, {'reward_formula': None, 'progress_text': 'Порушення зміни варти: {progress}/8'}),
    V2StoryQuestContentRecord('dark_forest_063_answer_from_the_forest', 63, 'Відповідь із лісу', 'TALK', 'dark_forest', 7, 'dark_forest_062_changing_of_the_guard', 'mercenary_head', 'mercenary_head', 1, 'Після зриву зміни варти розвідники помітили незвичний спосіб передавання сигналів між гоблінськими стоянками.', 'Отримати від Голови Найманців результати спостереження за гоблінськими патрулями.', 'Після твого удару патрулі почали відступати в різні боки. Один із дозорних подав короткий звуковий сигнал, а через кілька миттєвостей із глибини лісу надійшла відповідь.\n\nІнші гобліни одразу змінили напрямок руху. Отже, звук був не випадковим попередженням, а наказом.\n\nРозвідники не змогли роздивитися предмет, яким скористався дозорний. Вони лише помітили, що гоблін підніс до обличчя щось невелике, прикріплене до пояса.', 'Голова Найманців підтверджує, що гоблінські стоянки обмінюються звуковими сигналами.', 75, 2.36, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_064_voice_of_the_patrol', 64, 'Голос дозору', 'QUEST_ITEM', 'dark_forest', 7, 'dark_forest_063_answer_from_the_forest', 'mercenary_head', 'mercenary_head', 1, 'Знайти предмет, за допомогою якого гоблінські дозорні передають звукові сигнали.', 'Шукати під час полювання предмет для передавання сигналів.', 'Тепер ми знаємо, що дозорні використовують невеликий предмет, який носять на поясі.\n\nПродовжуй полювання поблизу внутрішніх стежок. Нам потрібен один цілий екземпляр, а не випадковий уламок.\n\nНе намагайся самостійно відтворювати почутий сигнал. Ми ще не знаємо, що саме він означає і хто може на нього відповісти.', 'Знайдено цілий гоблінський сигнальний ріг із насічками на металевому обручі.', 75, 2.36, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_goblin_signal_horn', 'display_name': 'Гоблінський сигнальний ріг', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Гоблінський сигнальний ріг'}, 'first_drop_text': 'Знайдений предмет виявився коротким рогом, обтягнутим темною шкірою. Металевий обруч укритий короткими й довгими насічками.', 'progress_text': 'Пошук предмета гоблінського дозору: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Голос дозору', 'post_reveal_title': 'Голос дозору', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'blacksmith', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → ⚒️ Коваль'}}),
    V2StoryQuestContentRecord('dark_forest_065_notches_on_the_band', 65, 'Насічки на обручі', 'TURN_IN', 'dark_forest', 7, 'dark_forest_064_voice_of_the_patrol', 'blacksmith', 'blacksmith', 1, 'Передати Ковалю сигнальний ріг для огляду металевого обруча та насічок.', 'Передати Ковалю гоблінський сигнальний ріг.', 'Сам ріг зроблено грубо, але металевий обруч виготовлено значно уважніше.\n\nГобліни нагріли залізо на слабкому вогні, а потім затягнули його на місце, поки метал залишався м’яким. Короткі та довгі насічки нанесено вже після охолодження.\n\nВони розташовані групами й не схожі на звичайні прикраси. Можливо, кожна група відповідає окремому звуковому сигналу.\n\nНа внутрішньому боці обруча також є знак із трьома зубцями над ламаною лінією. Я раніше такого символу не бачив.', 'Коваль приймає сигнальний ріг і підтверджує, що насічки нанесено навмисно та розподілено на окремі групи.', 75, 2.36, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_goblin_signal_horn', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'trader', 'route_text': '🏙️ Місто → 🛒 Торговий ряд → 🧙 Торговець'}}),
    V2StoryQuestContentRecord('dark_forest_066_three_pronged_mark', 66, 'Знак із трьома зубцями', 'TALK', 'dark_forest', 7, 'dark_forest_065_notches_on_the_band', 'trader', 'trader', 1, 'Торговець може знати походження символу, нанесеного на внутрішній бік металевого обруча.', 'Розпитати Торговця про знак із трьома зубцями.', 'Так, цей символ мені знайомий.\n\nКілька місяців тому знак із трьома зубцями з’явився на ящиках із припасами, які перевозили північною дорогою. Караван зник ще до того, як дістався Початку Шляху.\n\nПізніше мисливці знайшли порожні вози, але більшість вантажу зникла. Ми вирішили, що це звичайне пограбування.\n\nЯкщо той самий знак нанесено на ріг гоблінського дозору, викрадений вантаж міг потрапити до їхніх стоянок.', 'Торговець упізнає знак із трьома зубцями та пов’язує його зі зниклим караваном.', 75, 2.36, {'reward_formula': None, 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_067_cut_the_supply_line', 67, 'Перерізати постачання', 'KILL_REGION', 'dark_forest', 7, 'dark_forest_066_three_pronged_mark', 'mercenary_head', 'mercenary_head', 10, 'Відомості Торговця дозволили розвідникам визначити стежку, якою гобліни перевозять викрадені припаси.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Розвідники перевірили західну стежку. Нею регулярно проходять гоблінські загони з мішками та невеликими ящиками.\n\nЩо міститься у вантажі та куди саме його несуть, поки невідомо. Але якщо зупинити охорону стежки, рух припасів буде порушено.\n\nПереможи десять ворогів у Темному Борі й повернися з доповіддю. Не підпалюй ящики та не намагайся самостійно переслідувати носіїв углиб лісу.', 'Охорону західної стежки розбито. Рух гоблінських припасів через цю ділянку зупинено.', 75, 2.36, {'reward_formula': None, 'progress_text': 'Переривання постачання: {progress}/10'}),
    V2StoryQuestContentRecord('dark_forest_068_heavy_token', 68, 'Важкий жетон', 'QUEST_ITEM', 'dark_forest', 7, 'dark_forest_067_cut_the_supply_line', 'mercenary_head', 'mercenary_head', 1, 'Після бою розвідники помітили, що окремі гоблінські дозорні носять на поясах металеві предмети.', 'Шукати під час полювання металевий предмет гоблінського дозорного.', 'Під час зачистки розвідники помітили незвичну деталь. Деякі дозорні носили на поясах важкі металеві предмети.\n\nЗдалеку неможливо визначити, чи це прикраса, перепустка або знак належності до окремого загону.\n\nЗнайди один цілий предмет. Не намагайся використати його та не показуй гоблінам, якщо вони помітять тебе раніше.', 'Знайдено важкий залізний жетон із символом трьох зубців і сімома зарубками на звороті.', 75, 2.36, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_goblin_patrol_command_token', 'display_name': 'Командний жетон гоблінського дозору', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Командний жетон гоблінського дозору'}, 'first_drop_text': 'Знайдений предмет виявився важким залізним жетоном. На лицьовому боці вибито три зубці над ламаною лінією, а на звороті нанесено сім коротких зарубок.', 'progress_text': 'Пошук металевого предмета дозорного: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Важкий жетон', 'post_reveal_title': 'Важкий жетон', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'trader', 'route_text': '🏙️ Місто → 🛒 Торговий ряд → 🧙 Торговець'}}),
    V2StoryQuestContentRecord('dark_forest_069_seven_notches', 69, 'Сім зарубок', 'TALK', 'dark_forest', 7, 'dark_forest_068_heavy_token', 'trader', 'trader', 1, 'Показати Торговцю залізний жетон і з’ясувати можливе значення семи зарубок.', 'Показати Торговцю командний жетон гоблінського дозору.', 'Символ на лицьовому боці такий самий, як на зниклих ящиках. Але сім зарубок на звороті мають інше призначення.\n\nКараванники використовували подібні позначки, коли товари прямували до одного з кількох пунктів. Кількість зарубок могла вказувати на маршрут або кінцеве місце доставки.\n\nЯкщо гобліни перейняли цю систему, жетон пов’язаний із сьомим внутрішнім маршрутом. Більше я за ним визначити не зможу.', 'Торговець оглядає жетон і підтверджує, що сім зарубок можуть позначати окремий маршрут або кінцевий пункт доставки.', 75, 2.36, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_goblin_patrol_command_token', 'quantity': 1, 'consume': False}], 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_070_seventh_camp', 70, 'Сьома стоянка', 'TURN_IN', 'dark_forest', 7, 'dark_forest_069_seven_notches', 'mercenary_head', 'mercenary_head', 1, 'Передати Голові Найманців жетон із сімома зарубками для зіставлення з картою гоблінських маршрутів.', 'Передати Голові Найманців командний жетон гоблінського дозору.', 'Сім зарубок пояснюють те, що досі не складалося в єдину картину.\n\nРозвідники знайшли шість внутрішніх стоянок, але патрулів і припасів було більше, ніж ці табори могли прийняти.\n\nЯкщо кожна зарубка позначає окремий маршрут, у Темному Борі існує ще одна стоянка. Її немає на наших картах, а всі відомі стежки закінчуються раніше.\n\nЯ залишу жетон для порівняння з маршрутами розвідників. Тепер ми маємо доказ, що мережа гоблінських дозорів більша, ніж здавалося.', 'Голова Найманців приймає жетон і підтверджує існування сьомого внутрішнього маршруту.\n\nГоблінські дозори мають спільну систему сигналів, використовують викрадені припаси й підтримують щонайменше сім окремих маршрутів.\n\n✅ Розділ «Гоблінські дозори» завершено.', 75, 2.36, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_goblin_patrol_command_token', 'quantity': 1, 'consume': True}], 'next_quest_preview': {'number': 71, 'giver_npc_id': 'mercenary_head', 'unlock_level': 8}}),
)

def validate_story_dark_forest_61_70() -> None:
    quests=STORY_DARK_FOREST_61_70
    if len(quests)!=10 or [q.number for q in quests]!=list(range(61,71)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='dark_forest_060_threat_from_the_depths': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=7 or quest.location_id!='dark_forest': raise ValueError('invalid_level_or_location')
        if quest.reward_exp < 0 or quest.reward_gold < 0: raise ValueError('invalid_reward')

validate_story_dark_forest_61_70()
